"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8830],{53407:e=>{e.exports=JSON.parse('{"functions":[{"name":"targetCFrame","desc":"Where a placement\'s model belongs, in world space.","params":[{"name":"item","desc":"","lua_type":"Placement"},{"name":"baseX","desc":"Chunk origin column, in world cells.","lua_type":"number"},{"name":"baseY","desc":"Chunk origin row, in world cells.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"CFrame"}],"function_type":"static","private":true,"source":{"line":37,"path":"src/main/server/utils/placement.luau"}},{"name":"beginNext","desc":"Starts the job\'s next placement and advances past it.\\n\\nReturns as soon as the clone is *queued*, not when it is built \u2014 the entity\\ngains its `PlacementModel` and loses `Processing` later, from the completion\\ncallback. The job therefore moves on immediately and several placements can\\nbe in flight at once.\\n\\nPositioning happens on completion rather than at enqueue time because\\n`slowClone` hands back an empty root; pivoting it before its parts exist\\nwould move nothing.\\n\\nThe completion callback re-checks its destination. Streaming takes frames, and\\nthe chunk can be torn down in the meantime \u2014 without that check the finished\\nmodel would be parented into a detached folder and leak.","params":[{"name":"world","desc":"Named explicitly: this function writes components.","lua_type":"jecs.World"},{"name":"assets","desc":"For the prefab root.","lua_type":"BuildAssets"},{"name":"cache","desc":"Missing-prefab warnings.","lua_type":"PrefabCache"},{"name":"job","desc":"Mutated: its placement index advances.","lua_type":"BuildJob"}],"returns":[],"function_type":"static","source":{"line":65,"path":"src/main/server/utils/placement.luau"}}],"properties":[],"types":[],"name":"placement","desc":"Building one prefab into the world.\\n\\nA placement is never cloned whole. Its hierarchy is copied node by node\\nthrough [slowClone], out of sight and interruptible, and only admitted to the\\nworld once it is finished \u2014 which is what keeps a 272-part house from landing\\nas one uninterruptible spike.\\n\\nThe entity is tagged `Processing` for the whole of that, so nothing shows,\\nhides or rebuilds it mid-stream.","tags":["server-util"],"realm":["Server"],"source":{"line":16,"path":"src/main/server/utils/placement.luau"}}')}}]);